    28	extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
    29	  poppler::set_debug_error_function(nop_func, nullptr);
    30	
    31	  poppler::document *doc = poppler::document::load_from_raw_data((const char *)data, size);
    32	  if (!doc || doc->is_locked()) {
    33	    delete doc;
    34	    return 0;
    35	  }
    36	
    37	  poppler::page_renderer r;
    38	  for (int i = 0; i < doc->pages(); i++) {
    39	    poppler::page *p = doc->create_page(i);
    40	    if (!p) {
    41	      continue;
    42	    }
    43	    r.render_page(p);
    44	    p->text_list();
    45	    delete p;
    46	  }
    47	
    48	  delete doc;
    49	  return 0;
